//! Godot scene manifest: JSON generated by Godot through `kiln astra-manifest`.
//! A technical artifact, not a content source: the RON definitions are the
//! source of truth and this file is only compared against them.

use super::{Definition, Parsed};
use crate::catalog::{Finding, Severity};
use serde::{Deserialize, Serialize};
use std::path::Path;

#[derive(Debug, Clone, PartialEq, Serialize, Deserialize)]
pub struct Manifest {
    pub version: u32,
    pub scenes: Vec<SceneEntry>,
}

#[derive(Debug, Clone, PartialEq, Serialize, Deserialize)]
pub struct SceneEntry {
    /// `res://` path of the scene.
    pub scene: String,
    pub nodes: Vec<Node>,
}

#[derive(Debug, Clone, PartialEq, Serialize, Deserialize)]
pub struct Node {
    pub id: String,
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub connects: Option<[String; 2]>,
}

fn finding(severity: Severity, subject: String, code: &str, message: String) -> Finding {
    Finding {
        severity,
        subject,
        code: code.into(),
        message,
    }
}

pub fn load(root: &Path, rel: &str) -> Result<Manifest, Finding> {
    let text = std::fs::read_to_string(root.join(rel)).map_err(|_| {
        finding(
            Severity::Warn,
            rel.into(),
            "astra_manifest_missing",
            "manifiesto de Godot ausente: ejecuta `kiln astra-manifest`".into(),
        )
    })?;
    serde_json::from_str(&text).map_err(|e| {
        finding(
            Severity::Error,
            rel.into(),
            "astra_manifest_syntax",
            format!("línea {}, columna {}: {}", e.line(), e.column(), e),
        )
    })
}

fn same_pair(a: &[String; 2], b: &(String, String)) -> bool {
    (a[0] == b.0 && a[1] == b.1) || (a[0] == b.1 && a[1] == b.0)
}

pub fn compare(files: &[Parsed], m: &Manifest, manifest_rel: &str) -> Vec<Finding> {
    let mismatch = |subject: String, message: String| {
        finding(Severity::Error, subject, "astra_manifest_mismatch", message)
    };
    let nodes = || {
        m.scenes
            .iter()
            .flat_map(|s| s.nodes.iter().map(move |n| (s, n)))
    };
    let mut out = Vec::new();
    for p in files {
        for def in &p.defs {
            let subject = format!("{}#{}", p.file, def.id());
            match def {
                Definition::Sector { id, scene } => {
                    let in_scene = m
                        .scenes
                        .iter()
                        .any(|s| s.scene == *scene && s.nodes.iter().any(|n| n.id == *id));
                    if in_scene {
                        continue;
                    }
                    let other = nodes().find(|(_, n)| n.id == *id).map(|(s, _)| s);
                    out.push(mismatch(
                        subject,
                        match other {
                            Some(s) => format!(
                                "el sector está en la escena {} del manifiesto, pero la definición dice {}",
                                s.scene, scene
                            ),
                            None => format!("el sector no aparece en la escena {scene} del manifiesto"),
                        },
                    ));
                }
                Definition::Door { id, connects } => match nodes().find(|(_, n)| n.id == *id) {
                    None => out.push(mismatch(
                        subject,
                        "la puerta no aparece en el manifiesto".into(),
                    )),
                    Some((_, n)) => match &n.connects {
                        Some(c) if same_pair(c, connects) => {}
                        found => out.push(mismatch(
                            subject,
                            format!(
                                "conexiones distintas: definición ({}, {}), manifiesto {}",
                                connects.0,
                                connects.1,
                                found.as_ref().map_or("ninguna".to_string(), |c| format!(
                                    "({}, {})",
                                    c[0], c[1]
                                )),
                            ),
                        )),
                    },
                },
                _ => {}
            }
        }
    }
    for (_, n) in nodes() {
        let known = files.iter().flat_map(|p| &p.defs).any(|d| d.id() == n.id);
        if !known {
            out.push(mismatch(
                format!("{manifest_rel}#{}", n.id),
                "el nodo del manifiesto no tiene definición RON".into(),
            ));
        }
    }
    out
}

#[cfg(test)]
mod tests {
    use super::*;

    fn node(id: &str, c: Option<[&str; 2]>) -> Node {
        Node {
            id: id.into(),
            connects: c.map(|[a, b]| [a.into(), b.into()]),
        }
    }

    fn manifest(scenes: Vec<(&str, Vec<Node>)>) -> Manifest {
        Manifest {
            version: 1,
            scenes: scenes
                .into_iter()
                .map(|(s, nodes)| SceneEntry {
                    scene: s.into(),
                    nodes,
                })
                .collect(),
        }
    }

    fn files() -> Vec<Parsed> {
        vec![Parsed {
            file: "astra/a.ron".into(),
            defs: vec![
                Definition::Sector {
                    id: "sector:w".into(),
                    scene: "res://w.tscn".into(),
                },
                Definition::Sector {
                    id: "sector:y".into(),
                    scene: "res://y.tscn".into(),
                },
                Definition::Door {
                    id: "door:wy".into(),
                    connects: ("sector:w".into(), "sector:y".into()),
                },
                Definition::Object {
                    id: "object:crate".into(),
                    asset: "p/c".into(),
                },
            ],
        }]
    }

    fn good() -> Manifest {
        manifest(vec![
            (
                "res://w.tscn",
                vec![
                    node("sector:w", None),
                    node("door:wy", Some(["sector:w", "sector:y"])),
                ],
            ),
            ("res://y.tscn", vec![node("sector:y", None)]),
        ])
    }

    #[test]
    fn load_missing_file_warns() {
        let dir = std::env::temp_dir().join(format!("kiln-astra-manifest-{}", std::process::id()));
        let f = load(&dir, "nope.json").unwrap_err();
        assert_eq!(f.code, "astra_manifest_missing");
        assert!(f.severity == Severity::Warn);
        assert_eq!(f.subject, "nope.json");
        assert!(f.message.contains("kiln astra-manifest"));
    }

    #[test]
    fn load_broken_json_errors() {
        let dir = std::env::temp_dir().join(format!("kiln-astra-manifest-{}", std::process::id()));
        std::fs::create_dir_all(&dir).unwrap();
        std::fs::write(dir.join("m.json"), "{\n  \"version\": }").unwrap();
        let f = load(&dir, "m.json").unwrap_err();
        assert_eq!(f.code, "astra_manifest_syntax");
        assert!(f.severity == Severity::Error);
        assert!(f.message.contains("línea 2"), "{}", f.message);
    }

    #[test]
    fn load_valid_json() {
        let dir = std::env::temp_dir().join(format!("kiln-astra-manifest-{}", std::process::id()));
        std::fs::create_dir_all(&dir).unwrap();
        let json = r#"{ "version": 1, "scenes": [ { "scene": "res://w.tscn", "nodes": [ { "id": "sector:w" }, { "id": "door:wy", "connects": ["sector:w", "sector:y"] } ] } ] }"#;
        std::fs::write(dir.join("ok.json"), json).unwrap();
        let m = load(&dir, "ok.json").unwrap();
        assert_eq!(
            m.scenes[0].nodes[1].connects,
            Some(["sector:w".into(), "sector:y".into()])
        );
    }

    #[test]
    fn matching_is_clean() {
        assert!(compare(&files(), &good(), "m.json").is_empty());
    }

    #[test]
    fn sector_missing() {
        let m = manifest(vec![
            (
                "res://w.tscn",
                vec![node("door:wy", Some(["sector:w", "sector:y"]))],
            ),
            ("res://y.tscn", vec![node("sector:y", None)]),
        ]);
        let got = compare(&files(), &m, "m.json");
        assert_eq!(got.len(), 1);
        assert_eq!(got[0].subject, "astra/a.ron#sector:w");
        assert_eq!(got[0].code, "astra_manifest_mismatch");
    }

    #[test]
    fn sector_in_another_scene() {
        let m = manifest(vec![
            (
                "res://w.tscn",
                vec![node("door:wy", Some(["sector:w", "sector:y"]))],
            ),
            (
                "res://y.tscn",
                vec![node("sector:y", None), node("sector:w", None)],
            ),
        ]);
        let got = compare(&files(), &m, "m.json");
        assert_eq!(got.len(), 1);
        assert!(got[0].message.contains("res://y.tscn") && got[0].message.contains("res://w.tscn"));
    }

    #[test]
    fn door_connects_differ() {
        let mut m = good();
        m.scenes[0].nodes[1].connects = Some(["sector:w".into(), "sector:z".into()]);
        let got = compare(&files(), &m, "m.json");
        assert_eq!(got.len(), 1);
        assert_eq!(got[0].subject, "astra/a.ron#door:wy");
        assert!(got[0].message.contains("sector:z") && got[0].message.contains("sector:y"));
    }

    #[test]
    fn door_connects_reversed_is_fine() {
        let mut m = good();
        m.scenes[0].nodes[1].connects = Some(["sector:y".into(), "sector:w".into()]);
        assert!(compare(&files(), &m, "m.json").is_empty());
    }

    #[test]
    fn door_missing_or_without_connects() {
        let mut m = good();
        m.scenes[0].nodes[1].connects = None;
        assert_eq!(compare(&files(), &m, "m.json").len(), 1);
        m.scenes[0].nodes.remove(1);
        let got = compare(&files(), &m, "m.json");
        assert_eq!(got.len(), 1);
        assert!(got[0].message.contains("no aparece"));
    }

    #[test]
    fn extra_manifest_id() {
        let mut m = good();
        m.scenes[1].nodes.push(node("sector:ghost", None));
        let got = compare(&files(), &m, "m.json");
        assert_eq!(got.len(), 1);
        assert_eq!(got[0].subject, "m.json#sector:ghost");
    }
}
